0f2f0d69d4651b00f920b84d2760febe2fe0a2f0:
mutation StudentLoginMutation(
  $input: StudentLoginMutationInput!
) {
  studentLogin(input: $input) {
    error {
      field
      userMessage
    }
    student {
      id
    }
  }
}

5fee6c434dbc98a57b4f70383561d95429b2c618:
query HomePageQuery {
  student {
    RM
    fullname
    firstname
    lastname
    ...Menu_student
    ...Profile_student
    schoolReport {
      year
      ...SchoolReport_schoolReport
      id
    }
    id
  }
}

fragment AvatarBackground_student on Student {
  ...Avatar_student
}

fragment AvatarImage_student on Student {
  avatarURL
  firstname
  lastname
}

fragment AvatarPhotoDialog_student on Student {
  id
  avatarURL
  ...AvatarImage_student
}

fragment Avatar_student on Student {
  ...AvatarImage_student
  ...OpenUploadAvatarModalButton_student
}

fragment Information_student on Student {
  RM
  fullname
  schoolReport {
    year
    schoolReportRows {
      edges {
        node {
          disciplineName
          firstBimesterGrade
          firstBimesterRecGrade
          firstBimesterAbsences
          secondBimesterGrade
          secondBimesterRecGrade
          secondBimesterAbsences
          thirdBimesterGrade
          thirdBimesterRecGrade
          thirdBimesterAbsences
          fourthBimesterGrade
          fourthBimesterRecGrade
          fourthBimesterAbsences
          id
        }
      }
    }
    id
  }
}

fragment Menu_student on Student {
  firstname
}

fragment OpenUploadAvatarModalButton_student on Student {
  ...AvatarPhotoDialog_student
}

fragment Profile_student on Student {
  ...Information_student
  ...AvatarBackground_student
}

fragment SchoolReportTable_schoolReport on SchoolReport {
  schoolReportRows {
    edges {
      node {
        disciplineName
        firstBimesterGrade
        firstBimesterRecGrade
        firstBimesterAbsences
        secondBimesterGrade
        secondBimesterRecGrade
        secondBimesterAbsences
        thirdBimesterGrade
        thirdBimesterRecGrade
        thirdBimesterAbsences
        fourthBimesterGrade
        fourthBimesterRecGrade
        fourthBimesterAbsences
        id
      }
    }
  }
}

fragment SchoolReport_schoolReport on SchoolReport {
  year
  ...SchoolReportTable_schoolReport
  schoolReportRows {
    count
  }
}

